import os

from . import taf_config
from ute_ue import ute_ue
from ute_ue import PythonApi as utePythonApi
from .ute_ue_config_source import TAFTranslatedConfigSource


class ue(ute_ue):
    def __new__(cls, test_line_config=None, config_path="", *args, **kwargs):
        """Overrides config method from ute_ue"""
        ute_ue_obj = super().__new__(cls, *args, **kwargs)
        ute_ue_obj._python_api = bool(config_path) or test_line_config is not None
        if test_line_config:  # Load config for python API
            taf_config.collector.config = test_line_config
        elif config_path:
            os.environ["ABSTRACT_LIB_CONFIG"] = config_path
        ute_ue_obj._config_source = TAFTranslatedConfigSource()
        return ute_ue_obj


class PythonApi(utePythonApi):
    """
    Python Api class

    Serves as a wrapper class for starting a test suite in Python Api
    """
    def __init__(self, start=True, test_line_config=None, config_path=None):
        """
        __init__
        :param start: if true starts the test suite when the object is initialized
        :param test_line_config: test line configuration defined in a python __init__.py file
        :param config_path: test line configuration from a yaml file
        """
        self.ute_ue = None
        self.config_path = config_path
        self.test_line_config = test_line_config
        if self.config_path:
            super().__init__(start, config_path)
        elif self.test_line_config and start:
            self.start()

    def start(self):
        """
        Start

        Initializes the ute_ue object and starts the test suite
        """
        self.ute_ue = ue(self.test_line_config, self.config_path)
        self.ute_ue._python_api = True
        if hasattr(self.ute_ue, 'start_python_scope'):
            self.ute_ue.start_python_scope()
